$email='officer@example.org';$now=time();$messages=[];$transport=function($to,$subject,$body)use(&$messages){$messages[]=[$to,$subject,$body];return true;};
$code=function()use(&$messages){preg_match('/code is: ([0-9]{6})/',$messages[array_key_last($messages)][2],$m);return $m[1]??'';};
