check(PasswordReset::enabled($db),'enabled with schema and sender');
check(PasswordReset::email(['invalid'])==='','malformed email field');check(PasswordReset::email(' OFFICER@EXAMPLE.ORG ')===$email,'email normalized');
PasswordReset::request($db,$email,$transport,$now);check(count($messages)===1,'email sent');check(strlen($code())===6,'six-digit OTP');
