check(PasswordReset::complete($db,$email,$code(),$password,$password,$now+20),'valid reset succeeds');$updated=$db->query("SELECT * FROM users WHERE email='$email'")->fetch();check(password_verify($password,$updated['password_hash']),'password changed');check(!Security::sessionPasswordMatches($updated,$oldStamp),'old session invalidated');check(!Security::sessionPasswordMatches($updated,[]),'legacy session invalidated');check($old['transaction_pin_hash']===$updated['transaction_pin_hash']&&$old['role']===$updated['role'],'PIN and role unchanged');check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now+21),'OTP replay denied');
check((int)$db->query("SELECT COUNT(*) FROM security_audit_logs WHERE event_type='password_reset'")->fetchColumn()===1,'reset audited without OTP');
$fresh();PasswordReset::request($db,$email,$transport,$now);check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now+600),'expired at boundary');
$fresh();PasswordReset::request($db,$email,$transport,$now);$good=$code();$wrong=$good==='111111'?'222222':'111111';for($i=0;$i<5;$i++)check(!PasswordReset::complete($db,$email,$wrong,$password,$password,$now),'bad OTP attempt');check(!PasswordReset::complete($db,$email,$good,$password,$password,$now),'attempt cap locks even correct OTP');
$fresh();PasswordReset::request($db,$email,$transport,$now);$oldCode=$code();PasswordReset::request($db,$email,$transport,$now+61);check(count($messages)===2,'resend after cooldown');if($oldCode!==$code())check(!PasswordReset::complete($db,$email,$oldCode,$password,$password,$now+62),'superseded code rejected');check(PasswordReset::complete($db,$email,$code(),$password,$password,$now+63),'newest code succeeds');
$fresh();for($i=0;$i<4;$i++)PasswordReset::request($db,$email,$transport,$now+$i*61);check(count($messages)===3,'email issuance rate limit');
$fresh();for($i=0;$i<6;$i++)PasswordReset::request($db,'unknown'.$i.'@example.org',$transport,$now);check(count($messages)===0,'unknown accounts never emailed');check((int)$db->query('SELECT COUNT(*) FROM password_resets')->fetchColumn()===5,'IP request cap bounds allocation');check((int)$db->query('SELECT COUNT(*) FROM password_resets WHERE code_hash IS NOT NULL')->fetchColumn()===0,'unknown accounts have no codes');
