$fresh();PasswordReset::request($db,$email,$transport,$now);$db->exec("UPDATE users SET is_suspended=1 WHERE email='$email'");check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now),'suspension after request enforced');
$fresh();PasswordReset::request($db,$email,$transport,$now);$db->prepare('UPDATE users SET password_hash=? WHERE email=?')->execute([password_hash('administrator-changed-password',PASSWORD_DEFAULT),$email]);check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now),'intervening password change invalidates code');
$fresh();PasswordReset::request($db,$email,$transport,$now);$db->prepare('UPDATE users SET email=? WHERE email=?')->execute(['changed@example.org',$email]);check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now),'changed email invalidates old inbox code');$db->prepare('UPDATE users SET email=? WHERE email=?')->execute([$email,'changed@example.org']);
