$fresh();PasswordReset::request($db,$email,$transport,$now);$db->exec("CREATE TRIGGER fail_reset_audit BEFORE INSERT ON security_audit_logs WHEN NEW.event_type='password_reset' BEGIN SELECT RAISE(ABORT,'test rollback'); END");$before=$db->query("SELECT password_hash FROM users WHERE email='$email'")->fetchColumn();refuses(fn()=>PasswordReset::complete($db,$email,$code(),$password,$password,$now),'audit failure rolls back');check($db->query("SELECT password_hash FROM users WHERE email='$email'")->fetchColumn()===$before&&!$db->inTransaction(),'password rollback atomic');$db->exec('DROP TRIGGER fail_reset_audit');check(PasswordReset::complete($db,$email,$code(),$password,$password,$now),'OTP remains valid after rollback');
$fresh();PasswordReset::request($db,$email,$transport,$now);for($i=0;$i<30;$i++)PasswordReset::complete($db,'missing@example.org','123456',$password,$password,$now);check(!PasswordReset::complete($db,$email,$code(),$password,$password,$now),'IP verify cap across accounts');check(PasswordReset::complete($db,$email,$code(),$password,$password,$now+901)===false,'expired after rate window');
