$db->exec("UPDATE security_settings SET setting_value='' WHERE setting_key='password_reset_sender'");check(PasswordReset::enabled($db),'blank sender defaults to enabled');check(PasswordReset::sender($db)==='treasury@example.org','installation email fallback');
$db->exec("UPDATE security_settings SET setting_value='' WHERE setting_key='notification_email';UPDATE users SET role='provincial_admin' WHERE email='officer@example.org'");check(PasswordReset::sender($db)===$email,'admin email fallback');
